xpath.script:
(function () {
    var root = document.documentElement;

    var SHOW_DELAY = 200;
    var MIN_VISIBLE = 400;
    var BOOT_MAX = 12000;
    var SLOW_AFTER = 20000;

    var WAIT_MSG = "Un momento…";
    var SLOW_MSG = "Esto está tardando más de lo normal…";

    var bootTimer = null;
    var showTimer = null;
    var slowTimer = null;
    var shownAt = 0;

    function stopBoot() {
        if (bootTimer) {
            window.clearTimeout(bootTimer);
            bootTimer = null;
        }
        root.className = root.className.replace(
            /(^|\s)o_cc_loading(\s|$)/,
            " "
        );
    }

    root.className += " o_cc_loading";
    bootTimer = window.setTimeout(stopBoot, BOOT_MAX);
    window.addEventListener("load", stopBoot);

    function byId(id) {
        return document.getElementById(id);
    }

    function announce(message) {
        var region = document.querySelector(".o_cc_ldr_sr");
        if (region) {
            region.textContent = message;
        }
    }

    // Everything beside the curtain is taken out of reach while
    // it is up: a form the visitor can still tab into under a
    // cover that says "wait" is a lie told to keyboard users.
    function setInert(state) {
        var curtain = byId("o_cc_ldr");
        if (!curtain) {
            return;
        }
        var siblings = curtain.parentNode.children;
        // Counted down so the loop needs no "less than": a raw
        // one is an invalid token inside an XML data file.
        var index;
        for (index = siblings.length - 1; index >= 0; index--) {
            var node = siblings[index];
            if (node === curtain) {
                continue;
            }
            if (node.classList.contains("o_cc_ldr_bar")) {
                continue;
            }
            if (node.classList.contains("o_cc_ldr_sr")) {
                continue;
            }
            if (state) {
                node.setAttribute("inert", "inert");
            } else {
                node.removeAttribute("inert");
            }
        }
    }

    function reveal() {
        showTimer = null;
        var curtain = byId("o_cc_ldr");
        if (!curtain) {
            return;
        }
        curtain.removeAttribute("hidden");
        setInert(true);
        shownAt = new Date().getTime();
        announce(WAIT_MSG);
        slowTimer = window.setTimeout(function () {
            var text = byId("o_cc_ldr_text");
            if (text) {
                text.textContent = SLOW_MSG;
            }
            announce(SLOW_MSG);
        }, SLOW_AFTER);
    }

    function reallyHide() {
        var curtain = byId("o_cc_ldr");
        if (curtain) {
            curtain.setAttribute("hidden", "hidden");
        }
        setInert(false);
        shownAt = 0;
    }

    function show() {
        if (showTimer) {
            return;
        }
        if (shownAt) {
            return;
        }
        showTimer = window.setTimeout(reveal, SHOW_DELAY);
    }

    function hide() {
        if (slowTimer) {
            window.clearTimeout(slowTimer);
            slowTimer = null;
        }
        if (showTimer) {
            window.clearTimeout(showTimer);
            showTimer = null;
            return;
        }
        if (!shownAt) {
            return;
        }
        var visible = new Date().getTime() - shownAt;
        if (visible >= MIN_VISIBLE) {
            reallyHide();
        } else {
            window.setTimeout(reallyHide, MIN_VISIBLE - visible);
        }
    }

    function markBusy(button) {
        if (!button) {
            return;
        }
        if (button.getAttribute("aria-busy") === "true") {
            return;
        }
        var box = button.getBoundingClientRect();
        button.style.minWidth = box.width + "px";
        button.style.minHeight = box.height + "px";
        var ring = document.createElement("span");
        ring.className = "o_cc_ldr_btnring";
        ring.setAttribute("aria-hidden", "true");
        button.classList.add("o_cc_ldr_busy");
        button.insertBefore(ring, button.firstChild);
        button.setAttribute("aria-busy", "true");
        // Deferred by a tick: disabling a control while the
        // browser is still serialising the form can drop its
        // name/value from the payload.
        window.setTimeout(function () {
            button.disabled = true;
        }, 0);
    }

    function submitButton(form, submitter) {
        if (submitter) {
            return submitter;
        }
        return form.querySelector(
            "button[type=submit], input[type=submit], button:not([type])"
        );
    }

    // Bubble phase, not capture: in-page validation that cancels
    // a submit runs as a listener too, and a capture listener on
    // document would fire before it and raise a curtain over a
    // form going nowhere.
    document.addEventListener("submit", function (ev) {
        if (ev.defaultPrevented) {
            return;
        }
        markBusy(submitButton(ev.target, ev.submitter));
        show();
    });

    document.addEventListener("click", function (ev) {
        if (ev.defaultPrevented) {
            return;
        }
        if (ev.button) {
            return;
        }
        if (ev.metaKey || ev.ctrlKey || ev.shiftKey || ev.altKey) {
            return;
        }
        var node = ev.target;
        while (node) {
            if (node.tagName === "A") {
                break;
            }
            node = node.parentNode;
        }
        if (!node) {
            return;
        }
        if (node.target) {
            if (node.target !== "_self") {
                return;
            }
        }
        if (node.hasAttribute("download")) {
            return;
        }
        var href = node.getAttribute("href") || "";
        if (!href) {
            return;
        }
        // In-page anchors and javascript: links reload nothing,
        // so there is no wait to report.
        if (href.charAt(0) === "#") {
            return;
        }
        if (href.indexOf("javascript:") === 0) {
            return;
        }
        show();
    });

    // Returning through the bfcache restores the DOM exactly as
    // it was left, curtain and busy button included. The button
    // is NOT revived on a timeout, only by a real page load:
    // a form that looks idle again while its first request may
    // still land is how double submissions happen.
    window.addEventListener("pageshow", function () {
        if (showTimer) {
            window.clearTimeout(showTimer);
            showTimer = null;
        }
        shownAt = 0;
        reallyHide();
        stopBoot();
    });
})();

(function () {
    var root = document.documentElement;
    var MAX_WAIT = 15000;

    function done() {
        root.className = root.className.replace(
            /(^|\s)o_cc_skel_on(\s|$)/,
            " "
        );
    }

    // Registered before anything that could throw, so the
    // skeleton always has someone left to take it down.
    root.className += " o_cc_skel_on";
    window.setTimeout(done, MAX_WAIT);
    window.addEventListener("load", function () {
        // `load` means every resource arrived, NOT that the
        // page has anything to show: Odoo boots its module
        // system after it, so the OWL account picker mounts
        // later and core leaves the form `d-none` until then.
        // Taking the skeleton down here unconditionally left a
        // blank card between the logo and "o continúa como
        // invitado" -- the gap the user photographed on
        // 2026-08-17, which is exactly the wait this is
        // supposed to be covering.
        //
        // So `load` is a chance to finish early, never a
        // reason to. If neither outcome is on screen yet the
        // observer below is still watching, and MAX_WAIT is
        // still the backstop.
        window.requestAnimationFrame(function () {
            if (ready()) {
                done();
            }
        });
    });

    function ready() {
        var form = document.querySelector(".oe_login_form");
        if (form) {
            if (!form.classList.contains("d-none")) {
                return true;
            }
        }
        // The other outcome: a returning visitor gets the
        // account picker instead of the form, and the form
        // stays hidden. Anything rendered into the component
        // means the boot is over just as much.
        var owl = document.querySelector(
            "owl-component[name='web.user_switch']"
        );
        if (owl) {
            if (owl.children.length) {
                return true;
            }
        }
        return false;
    }

    if (window.MutationObserver) {
        var observer = new window.MutationObserver(function () {
            if (ready()) {
                observer.disconnect();
                done();
            }
        });
        observer.observe(document.documentElement, {
            subtree: true,
            childList: true,
            attributes: true,
            attributeFilter: ["class"]
        });
    }

    // The bundle may already be cached and done before this
    // line runs, in which case no mutation is ever observed.
    if (ready()) {
        done();
    }
})();
